<template><div class="container">  <div class="home">    <!-- 轮播图 -->    <Carousel       v-model="carouselValue"       autoplay       autoplay-speed="3000"      loop      indicator-position="outside">      <CarouselItem v-for="(item, index) in carouselData" :key="index">        <img :src="item.image" :alt="item.title" class="carousel-image"/>        <div class="carousel-caption">          <h3>{{ item.title }}</h3>          <p>{{ item.description }}</p>        </div>      </CarouselItem>    </Carousel>    <!-- 文章列表 -->    <div class="article-list">      <h2>最新文章</h2>      <div class="article-item" v-for="(article, index) in articles" :key="article.id">        <div class="article-cover">          <img :src="article.cover || '/default-cover.jpg'" :alt="article.title"/>        </div>        <div class="article-content">          <h3 class="article-title">            <router-link :to="'/pageDetail/' + article.id">{{ article.title }}</router-link>          </h3>          <p class="article-meta">            <span class="article-type">{{ getTypeText(article.type) }}</span>            <span class="article-date">{{ formatDate(article.createTime) }}</span>            <span class="article-author">{{ article.username }}</span>          </p>          <p class="article-description">{{ article.description }}</p>          <div class="article-stats">            <span class="article-read"><i class="icon ion-ios-eye"></i> {{ article.readCount || 0 }}</span>            <span class="article-like"><i class="icon ion-ios-heart"></i> {{ article.likeCount || 0 }}</span>            <span class="article-comment"><i class="icon ion-ios-chatboxes"></i> {{ article.commentCount || 0 }}</span>          </div>        </div>      </div>      <!-- 分页 -->      <Pagination         v-if="total > 0"        :total="total"        :page-size="pageSize"        :current="currentPage"        @on-change="pageChange"        show-total        show-sizer        show-jumper>      </Pagination>    </div>  </div></div></template><script>import { formatDate } from '@/utils/formatDateUtils'export default {  name: 'home',  data() {    return {      carouselValue: 0,      carouselData: [        { image: '/carousel1.jpg', title: '欢迎来到我的博客', description: '分享技术，记录生活' },        { image: '/carousel2.jpg', title: '前端技术分享', description: 'Vue.js, React, JavaScript' },        { image: '/carousel3.jpg', title: '后端技术分享', description: 'Java, Spring Boot, MySQL' }      ],      articles: [],      total: 0,      pageSize: 10,      currentPage: 1,      isLoading: false    }  },  created() {    this.loadArticles()  },  methods: {    async loadArticles() {      this.isLoading = true      try {        const res = await this.axios.get('/articleController/list', {          params: {            page: this.currentPage,            size: this.pageSize          }        })        if (res.data.status === 999) {          this.$Message.error(res.data.msg)        } else if (res.data.status === 1000) {          this.$Message.error(res.data.msg)        } else if (res.data.status === 200) {          this.articles = res.data.data.list          this.total = res.data.data.total        }      } catch (error) {        this.$Message.error('加载文章失败，请稍后重试')        console.error(error)      } finally {        this.isLoading = false      }    },    pageChange(page) {      this.currentPage = page      this.loadArticles()    },    getTypeText(type) {      switch(type) {        case '0':          return '原创'        case '1':          return '转载'        case '2':          return '翻译'        default:          return '未知'      }    },    formatDate(date) {      return formatDate(date)    }  },  watch: {    carouselValue(newValue) {      if (newValue === 0) {        // 轮播到第一张图时的处理        console.log('轮播到第一张图')      }    }  }}</script><style scoped>.home {  max-width: 1200px;  margin: 0 auto;  padding: 20px;}/* 轮播图样式 */.carousel-image {  width: 100%;  height: 400px;  object-fit: cover;}.carousel-caption {  position: absolute;  bottom: 0;  left: 0;  right: 0;  background: rgba(0, 0, 0, 0.5);  color: white;  padding: 20px;}.carousel-caption h3 {  margin: 0 0 10px 0;  font-size: 24px;}.carousel-caption p {  margin: 0;  font-size: 16px;}/* 文章列表样式 */.article-list {  margin-top: 40px;}.article-list h2 {  font-size: 28px;  margin-bottom: 20px;  color: #303133;  border-bottom: 2px solid #409eff;  padding-bottom: 10px;}.article-item {  display: flex;  margin-bottom: 20px;  padding: 20px;  background: white;  border-radius: 8px;  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);  transition: all 0.3s;}.article-item:hover {  transform: translateY(-5px);  box-shadow: 0 4px 16px 0 rgba(0, 0, 0, 0.15);}.article-cover {  width: 200px;  height: 150px;  margin-right: 20px;  flex-shrink: 0;}.article-cover img {  width: 100%;  height: 100%;  object-fit: cover;  border-radius: 4px;}.article-content {  flex: 1;  display: flex;  flex-direction: column;  justify-content: space-between;}.article-title {  margin: 0 0 10px 0;  font-size: 20px;}.article-title a {  color: #303133;  text-decoration: none;}.article-title a:hover {  color: #409eff;}.article-meta {  margin: 0 0 10px 0;  font-size: 14px;  color: #909399;}.article-type {  margin-right: 15px;  padding: 2px 8px;  background: #ecf5ff;  color: #409eff;  border-radius: 4px;  font-size: 12px;}.article-date {  margin-right: 15px;}.article-description {  margin: 0 0 15px 0;  font-size: 14px;  color: #606266;  line-height: 1.6;  overflow: hidden;  text-overflow: ellipsis;  display: -webkit-box;  -webkit-line-clamp: 2;  -webkit-box-orient: vertical;}.article-stats {  font-size: 14px;  color: #909399;}.article-stats span {  margin-right: 20px;}.article-stats i {  margin-right: 5px;}/* 分页样式 */.ivu-page {  margin-top: 30px;  text-align: center;}/* 响应式设计 */@media (max-width: 768px) {  .home {    padding: 10px;  }    .carousel-image {    height: 200px;  }    .carousel-caption {    padding: 10px;  }    .carousel-caption h3 {    font-size: 18px;  }    .carousel-caption p {    font-size: 14px;  }    .article-list {    margin-top: 20px;  }    .article-list h2 {    font-size: 22px;    margin-bottom: 15px;  }    .article-item {    flex-direction: column;    padding: 15px;  }    .article-cover {    width: 100%;    height: 150px;    margin-right: 0;    margin-bottom: 15px;  }    .article-title {    font-size: 18px;  }    .article-meta {    font-size: 12px;  }    .article-description {    font-size: 12px;  }    .article-stats {    font-size: 12px;  }    .article-stats span {    margin-right: 10px;  }    .ivu-page {    margin-top: 20px;  }    .ivu-page-item {    padding: 0 6px;  }    .ivu-page-prev, .ivu-page-next {    padding: 0 6px;  }}@media (max-width: 480px) {  .carousel-image {    height: 150px;  }    .carousel-caption h3 {    font-size: 16px;  }    .carousel-caption p {    font-size: 12px;  }    .article-list h2 {    font-size: 20px;  }    .article-title {    font-size: 16px;  }    .article-cover {    height: 120px;  }}</style>